<?php
require __DIR__ . '/includes/auth.php'; require_admin(); require __DIR__ . '/config/database.php'; require __DIR__ . '/config/collection_schedule.php';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $id = (int)($_POST['request_id'] ?? 0); $status = $_POST['status'] ?? '';
    if ($id > 0 && in_array($status, ['approved','rejected'], true)) {
        $request = $pdo->prepare('SELECT requester_id,item_name,quantity,status FROM stationery_requests WHERE id=?');
        $request->execute([$id]); $request = $request->fetch();
        if ($request && $request['status'] === 'pending') {
            $pdo->prepare('UPDATE stationery_requests SET status=?, reviewed_at=NOW() WHERE id=?')->execute([$status,$id]);
            if ($status === 'approved' && $request['requester_id']) {
                $message = 'Your request for '.$request['quantity'].' x '.$request['item_name'].' is approved. Please collect it at '.COLLECTION_LOCATION.' on '.COLLECTION_DAY.', '.COLLECTION_TIME.'.';
                $note = $pdo->prepare('INSERT INTO notifications (user_id,request_id,title,message) VALUES (?,?,?,?)');
                $note->execute([$request['requester_id'],$id,'Stationery ready for collection',$message]);
            }
        }
    }
    header('Location: admin_requests.php'); exit;
}
$requests = $pdo->query('SELECT stationery_requests.*, users.email AS requester_email FROM stationery_requests LEFT JOIN users ON stationery_requests.requester_id=users.id ORDER BY CASE WHEN status="pending" THEN 0 ELSE 1 END, created_at DESC')->fetchAll();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SIMS | Staff Requests</title><link rel="stylesheet" href="assets/css/style.css"><style>.review-form{display:inline-flex;gap:6px}.review-form button{border:0;border-radius:5px;padding:7px 9px;color:white;cursor:pointer;font-size:12px}.approve{background:#159464}.reject{background:#df4960}.pending{background:#fff2c6;color:#a16207}.approved{background:#dcfce7;color:#15803d}.collected{background:#dbeafe;color:#1d4ed8}.rejected{background:#ffe4e6;color:#be123c}.collection-note{background:#edfcf6;border-left:4px solid #21a97d;padding:13px;border-radius:7px;color:#16684f;margin:18px 0;font-size:13px}</style></head><body class="dashboard-page"><aside class="sidebar"><div class="logo"><span>✎</span><div><strong>SIMS</strong><small>Stationery Inventory</small></div></div><nav><a href="dashboard.php">▦ Dashboard</a><a href="inventory.php">▤ Inventory</a><a class="active" href="admin_requests.php">✉ Staff requests</a><a href="manage_users.php">♙ Users</a><a href="reports.php">▥ Reports</a><a href="profile.php">♙ Profile</a></nav><a class="logout" href="logout.php">⇥ Sign out</a></aside><main class="dashboard"><header><div><p class="eyebrow">ADMIN PORTAL › STAFF REQUESTS</p><h1>Stationery Requests</h1><p class="muted">Approve or reject Staff requests.</p></div></header><div class="collection-note"><strong>Fixed collection schedule:</strong> When a request is approved, the Staff member is notified to collect the stationery at the <strong><?=COLLECTION_LOCATION?></strong> on <strong><?=COLLECTION_DAY?></strong>, <?=COLLECTION_TIME?>.</div><section class="content-card"><table><thead><tr><th>Staff member</th><th>Item</th><th>Category</th><th>Qty</th><th>Reason</th><th>Date</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if(!$requests):?><tr><td colspan="8">No staff requests yet.</td></tr><?php endif;?><?php foreach($requests as $r):?><tr><td><strong><?=htmlspecialchars($r['requester_name'])?></strong><br><small><?=htmlspecialchars($r['requester_email']??'')?></small></td><td><?=htmlspecialchars($r['item_name'])?></td><td><?=htmlspecialchars($r['category'])?></td><td><?= (int)$r['quantity']?></td><td><?=htmlspecialchars($r['reason']?:'-')?></td><td><?=date('d M Y',strtotime($r['created_at']))?></td><td><span class="badge <?=htmlspecialchars($r['status'])?>"><?=ucfirst(htmlspecialchars($r['status']))?></span><?php if($r['status']==='collected' && !empty($r['collected_at'])):?><br><small><?=date('d M Y, h:i A',strtotime($r['collected_at']))?></small><?php endif;?></td><td><?php if($r['status']==='pending'):?><form class="review-form" method="post"><input type="hidden" name="request_id" value="<?= (int)$r['id']?>"><button class="approve" name="status" value="approved">Approve</button><button class="reject" name="status" value="rejected">Reject</button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table></section></main></body></html>
